package com.exe201.rrms.controller;
import com.exe201.rrms.entity.*; import com.exe201.rrms.repository.*; import com.exe201.rrms.service.*; import jakarta.servlet.http.HttpServletRequest; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*; import java.util.stream.*;
@RestController @RequestMapping("/api/admin") public class AdminController {
 private final AuthService auth; private final UserRepository users; private final ListingRepository listings; private final PropertyRepository props; private final ModerationActionRepository mods; private final VerificationRecordRepository verifs; private final ReportRepository reports; private final PaymentRepository payments; private final PaymentService paymentService; private final WalletTransactionRepository txs; private final PackagePlanRepository plans; private final ServiceListingRepository services; private final SecondHandListingRepository secondHand; private final BlogPostRepository blogs; private final QuestionRepository questions; private final AnswerRepository answers; private final ReviewRepository reviews; private final AdvertisementRepository ads; private final ExpenseRepository expenses; private final NotificationService noti; private final AuditLogRepository audit;
 public AdminController(AuthService a,UserRepository u,ListingRepository l,PropertyRepository p,ModerationActionRepository m,VerificationRecordRepository v,ReportRepository r,PaymentRepository py,PaymentService ps,WalletTransactionRepository t,PackagePlanRepository pl,ServiceListingRepository s,SecondHandListingRepository sh,BlogPostRepository b,QuestionRepository q,AnswerRepository an,ReviewRepository rv,AdvertisementRepository ad,ExpenseRepository e,NotificationService n,AuditLogRepository au){auth=a;users=u;listings=l;props=p;mods=m;verifs=v;reports=r;payments=py;paymentService=ps;txs=t;plans=pl;services=s;secondHand=sh;blogs=b;questions=q;answers=an;reviews=rv;ads=ad;expenses=e;noti=n;audit=au;}
 private User admin(HttpServletRequest r,String... roles){User u=auth.current(r);String[] base=roles.length==0?new String[]{"ADMIN","SUPER_ADMIN","MODERATOR","VERIFIER","CONTENT_ADMIN","FINANCE_ADMIN"}:roles;auth.requireRole(u,base);return u;} private void log(Long actor,String action,String type,Long id,String d){AuditLog a=new AuditLog();a.setActorId(actor);a.setAction(action);a.setTargetType(type);a.setTargetId(id);a.setDetails(d);audit.save(a);}
 @GetMapping("/dashboard") public Map<String,Object> dashboard(HttpServletRequest r){admin(r);Map<String,Object> m=new LinkedHashMap<>();m.put("users",users.count());m.put("listings",listings.count());m.put("pendingListings",listings.findByStatus("PENDING_REVIEW").size());m.put("activeListings",listings.findByStatus("ACTIVE").size());m.put("staleListings",listings.findByStatus("HIDDEN_STALE").size());m.put("openReports",reports.findByStatusOrderByCreatedAtDesc("OPEN").size());m.put("pendingPayments",payments.findByStatusOrderByCreatedAtDesc("PENDING").size());m.put("verificationQueue",verifs.findByStatus("PENDING").size());long cashIn=payments.findAll().stream().filter(x->"PAID".equals(x.getStatus())).mapToLong(Payment::getAmount).sum();long expense=expenses.findAll().stream().mapToLong(Expense::getAmount).sum();m.put("cashIn",cashIn);m.put("expenses",expense);m.put("netCashFlow",cashIn-expense);return m;}
 @GetMapping("/users") public List<Map<String,Object>> userList(HttpServletRequest r){admin(r,"ADMIN","SUPER_ADMIN");return users.findAll().stream().map(auth::safeUser).toList();} @PutMapping("/users/{id}") public Map<String,Object> updateUser(@PathVariable Long id,HttpServletRequest r,@RequestBody Map<String,String>b){User a=admin(r,"ADMIN","SUPER_ADMIN");User u=users.findById(id).orElseThrow();if(b.get("role")!=null)u.setRole(b.get("role").toUpperCase());if(b.get("status")!=null)u.setStatus(b.get("status").toUpperCase());users.save(u);log(a.getId(),"UPDATE_USER","USER",id,b.toString());return auth.safeUser(u);}
 @GetMapping("/moderation") public List<Listing> moderation(HttpServletRequest r){admin(r,"ADMIN","SUPER_ADMIN","MODERATOR");return listings.findByStatusIn(List.of("PENDING_REVIEW","NEED_REVISION","SUSPENDED"));}
 @PostMapping("/listings/{id}/moderate") public Listing moderate(@PathVariable Long id,HttpServletRequest r,@RequestBody Map<String,String>b){User a=admin(r,"ADMIN","SUPER_ADMIN","MODERATOR");Listing l=listings.findById(id).orElseThrow();String action=b.getOrDefault("action","APPROVE").toUpperCase(),reason=b.get("reason");if("APPROVE".equals(action)){l.setStatus("ACTIVE");l.setPublishedAt(l.getPublishedAt()==null?LocalDateTime.now():l.getPublishedAt());l.setLastConfirmedAt(LocalDateTime.now());l.setFreshnessDueAt(LocalDateTime.now().plusDays(15));l.setRevisionNote(null);noti.send(l.getLandlordId(),"LISTING_APPROVED","Tin #"+id+" đã được duyệt.","LISTING",id);}else if("NEED_REVISION".equals(action)){l.setStatus("NEED_REVISION");l.setRevisionNote(reason);noti.send(l.getLandlordId(),"LISTING_NEED_REVISION","Tin #"+id+" cần sửa: "+reason,"LISTING",id);}else if("REJECT".equals(action)){l.setStatus("REJECTED");l.setRevisionNote(reason);noti.send(l.getLandlordId(),"LISTING_REJECTED","Tin #"+id+" bị từ chối: "+reason,"LISTING",id);}else if("SUSPEND".equals(action)){l.setStatus("SUSPENDED");l.setRevisionNote(reason);noti.send(l.getLandlordId(),"LISTING_SUSPENDED","Tin #"+id+" bị tạm khóa: "+reason,"LISTING",id);}listings.save(l);ModerationAction ma=new ModerationAction();ma.setListingId(id);ma.setModeratorId(a.getId());ma.setAction(action);ma.setReason(reason);mods.save(ma);log(a.getId(),action,"LISTING",id,reason);return l;}
 @GetMapping("/verifications") public List<VerificationRecord> verifications(HttpServletRequest r){admin(r,"ADMIN","SUPER_ADMIN","VERIFIER");return verifs.findAll();} @PostMapping("/verifications") public VerificationRecord verify(HttpServletRequest r,@RequestBody VerificationRecord v){User a=admin(r,"ADMIN","SUPER_ADMIN","VERIFIER");v.setId(null);v.setVerifierId(a.getId());v.setStatus("VERIFIED");v.setVerifiedAt(LocalDateTime.now());if(v.getExpiresAt()==null)v.setExpiresAt(LocalDateTime.now().plusDays(30));VerificationRecord x=verifs.save(v);log(a.getId(),"VERIFY_"+v.getLevel(),"LISTING",v.getListingId(),v.getNote());return x;}
 @GetMapping("/reports") public List<Report> reportList(HttpServletRequest r){admin(r,"ADMIN","SUPER_ADMIN","MODERATOR");return reports.findAll();} @PostMapping("/reports/{id}/resolve") public Report resolve(@PathVariable Long id,HttpServletRequest r,@RequestBody Map<String,String>b){User a=admin(r,"ADMIN","SUPER_ADMIN","MODERATOR");Report x=reports.findById(id).orElseThrow();x.setStatus("RESOLVED");x.setHandledBy(a.getId());x.setResolution(b.get("resolution"));x.setResolvedAt(LocalDateTime.now());reports.save(x);log(a.getId(),"RESOLVE_REPORT","REPORT",id,x.getResolution());return x;}
 @GetMapping("/payments") public List<Payment> paymentList(HttpServletRequest r){admin(r,"ADMIN","SUPER_ADMIN","FINANCE_ADMIN");return payments.findAll();} @PostMapping("/payments/{id}/confirm") public Map<String,Object> confirm(@PathVariable Long id,HttpServletRequest r){User a=admin(r,"ADMIN","SUPER_ADMIN","FINANCE_ADMIN");Payment p=payments.findById(id).orElseThrow();paymentService.markPaid(p);log(a.getId(),"CONFIRM_PAYMENT","PAYMENT",id,p.getCode());return Map.of("message","Đã xác nhận thanh toán");} @GetMapping("/finance") public Map<String,Object> finance(HttpServletRequest r){admin(r,"ADMIN","SUPER_ADMIN","FINANCE_ADMIN");List<Payment> ps=payments.findAll();long cashIn=ps.stream().filter(x->"PAID".equals(x.getStatus())).mapToLong(Payment::getAmount).sum();long topup=ps.stream().filter(x->"PAID".equals(x.getStatus())&&"WALLET_TOPUP".equals(x.getType())).mapToLong(Payment::getAmount).sum();long direct=ps.stream().filter(x->"PAID".equals(x.getStatus())&&"PACKAGE_DIRECT".equals(x.getType())).mapToLong(Payment::getAmount).sum();long packageSpend=txs.findAll().stream().filter(x->"DEBIT".equals(x.getType())).mapToLong(x->Math.abs(x.getAmount())).sum();long ex=expenses.findAll().stream().mapToLong(Expense::getAmount).sum();return Map.of("cashIn",cashIn,"walletTopup",topup,"directPurchase",direct,"walletPackageSpend",packageSpend,"expenses",ex,"netCashFlow",cashIn-ex,"payments",ps,"expenseItems",expenses.findAll());}
 @PostMapping("/expenses") public Expense expense(HttpServletRequest r,@RequestBody Expense e){User a=admin(r,"ADMIN","SUPER_ADMIN","FINANCE_ADMIN");e.setId(null);e.setCreatedBy(a.getId());return expenses.save(e);} @GetMapping("/plans") public List<PackagePlan> plans(HttpServletRequest r){admin(r,"ADMIN","SUPER_ADMIN","FINANCE_ADMIN");return plans.findAll();} @PostMapping("/plans") public PackagePlan plan(HttpServletRequest r,@RequestBody PackagePlan p){admin(r,"ADMIN","SUPER_ADMIN","FINANCE_ADMIN");return plans.save(p);}
 @GetMapping("/services") public List<ServiceListing> services(HttpServletRequest r){admin(r,"ADMIN","SUPER_ADMIN","MODERATOR");return services.findAll();} @PostMapping("/services/{id}/moderate") public ServiceListing serviceModerate(@PathVariable Long id,HttpServletRequest r,@RequestBody Map<String,String>b){admin(r,"ADMIN","SUPER_ADMIN","MODERATOR");ServiceListing s=services.findById(id).orElseThrow();s.setStatus(b.getOrDefault("status","ACTIVE"));return services.save(s);}

 @GetMapping("/secondhand") public List<SecondHandListing> secondHand(HttpServletRequest r){admin(r,"ADMIN","SUPER_ADMIN","MODERATOR");return secondHand.findAll();} @PostMapping("/secondhand/{id}/status") public SecondHandListing secondStatus(@PathVariable Long id,HttpServletRequest r,@RequestBody Map<String,String>b){User a=admin(r,"ADMIN","SUPER_ADMIN","MODERATOR");SecondHandListing x=secondHand.findById(id).orElseThrow();x.setStatus(b.getOrDefault("status","ACTIVE"));secondHand.save(x);log(a.getId(),"SECONDHAND_STATUS","SECOND_HAND",id,x.getStatus());return x;}
 @GetMapping("/questions") public List<Question> questions(HttpServletRequest r){admin(r,"ADMIN","SUPER_ADMIN","MODERATOR","CONTENT_ADMIN");return questions.findAll();} @PostMapping("/questions/{id}/status") public Question questionStatus(@PathVariable Long id,HttpServletRequest r,@RequestBody Map<String,String>b){User a=admin(r,"ADMIN","SUPER_ADMIN","MODERATOR","CONTENT_ADMIN");Question x=questions.findById(id).orElseThrow();x.setStatus(b.getOrDefault("status","VISIBLE"));questions.save(x);log(a.getId(),"QUESTION_STATUS","QUESTION",id,x.getStatus());return x;} @GetMapping("/answers") public List<Answer> answers(HttpServletRequest r){admin(r,"ADMIN","SUPER_ADMIN","MODERATOR","CONTENT_ADMIN");return answers.findAll();} @PostMapping("/answers/{id}/status") public Answer answerStatus(@PathVariable Long id,HttpServletRequest r,@RequestBody Map<String,String>b){User a=admin(r,"ADMIN","SUPER_ADMIN","MODERATOR","CONTENT_ADMIN");Answer x=answers.findById(id).orElseThrow();x.setStatus(b.getOrDefault("status","VISIBLE"));answers.save(x);log(a.getId(),"ANSWER_STATUS","ANSWER",id,x.getStatus());return x;}
 @GetMapping("/reviews") public List<Review> reviewList(HttpServletRequest r){admin(r,"ADMIN","SUPER_ADMIN","MODERATOR");return reviews.findAll();} @PostMapping("/reviews/{id}/status") public Review reviewStatus(@PathVariable Long id,HttpServletRequest r,@RequestBody Map<String,String>b){User a=admin(r,"ADMIN","SUPER_ADMIN","MODERATOR");Review x=reviews.findById(id).orElseThrow();x.setStatus(b.getOrDefault("status","VISIBLE"));reviews.save(x);log(a.getId(),"REVIEW_STATUS","REVIEW",id,x.getStatus());return x;}
 @GetMapping("/blogs") public List<BlogPost> blogList(HttpServletRequest r){admin(r,"ADMIN","SUPER_ADMIN","CONTENT_ADMIN");return blogs.findAll();} @PostMapping("/blogs") public BlogPost blogCreate(HttpServletRequest r,@RequestBody BlogPost b){User a=admin(r,"ADMIN","SUPER_ADMIN","CONTENT_ADMIN");b.setAuthorId(a.getId());if("PUBLISHED".equals(b.getStatus())&&b.getPublishedAt()==null)b.setPublishedAt(LocalDateTime.now());return blogs.save(b);} @PutMapping("/blogs/{id}") public BlogPost blogUpdate(@PathVariable Long id,HttpServletRequest r,@RequestBody BlogPost d){admin(r,"ADMIN","SUPER_ADMIN","CONTENT_ADMIN");d.setId(id);if("PUBLISHED".equals(d.getStatus())&&d.getPublishedAt()==null)d.setPublishedAt(LocalDateTime.now());return blogs.save(d);}
 @GetMapping("/ads") public List<Advertisement> ads(HttpServletRequest r){admin(r,"ADMIN","SUPER_ADMIN","CONTENT_ADMIN");return ads.findAll();} @PostMapping("/ads") public Advertisement ad(HttpServletRequest r,@RequestBody Advertisement a){admin(r,"ADMIN","SUPER_ADMIN","CONTENT_ADMIN");return ads.save(a);} @PutMapping("/ads/{id}") public Advertisement adUpdate(@PathVariable Long id,HttpServletRequest r,@RequestBody Advertisement a){admin(r,"ADMIN","SUPER_ADMIN","CONTENT_ADMIN");a.setId(id);return ads.save(a);} @GetMapping("/audit") public List<AuditLog> audit(HttpServletRequest r){admin(r,"SUPER_ADMIN","ADMIN");return audit.findTop200ByOrderByCreatedAtDesc();}
}
